fn main() {
    // Tauri embeds these icons in the development executable. Explicit Cargo
    // dependencies ensure changing an icon rebuilds the binary on every OS.
    for icon in [
        "icons/32x32.png",
        "icons/64x64.png",
        "icons/128x128.png",
        "icons/128x128@2x.png",
        "icons/icon.png",
        "icons/icon.icns",
        "icons/icon.ico",
    ] {
        println!("cargo:rerun-if-changed={icon}");
    }
    // Explicit globs exclude macOS AppleDouble metadata on external drives.
    // Permission files are checked in under permissions/autogenerated.
    println!("cargo:rerun-if-changed=permissions/autogenerated");
    println!("cargo:rerun-if-changed=capabilities");
    let manifest = tauri_build::AppManifest::new()
        .permissions_path_pattern("permissions/autogenerated/[a-z]*.toml");
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(manifest)
            .capabilities_path_pattern("capabilities/[a-z]*.json"),
    )
    .expect("Failed to load native command permissions");
}
